"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[4863],{92635(a,n,e){e.r(n),e.d(n,{assets:()=>r,contentTitle:()=>m,default:()=>g,frontMatter:()=>k,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"learning/courses/quantum-business-foundations/quantum-technology","title":"Teknologi Kuantum","description":"Kenali bahawa menyelesaikan masalah bermakna akan melibatkan gabungan sumber kuantum dan klasikal.","source":"@site/i18n/ms/docusaurus-plugin-content-docs/current/learning/courses/quantum-business-foundations/quantum-technology.mdx","sourceDirName":"learning/courses/quantum-business-foundations","slug":"/learning/courses/quantum-business-foundations/quantum-technology","permalink":"/learning/courses/quantum-business-foundations/quantum-technology","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-business-foundations/quantum-technology.mdx","tags":[],"version":"current","frontMatter":{"title":"Teknologi Kuantum","description":"Kenali bahawa menyelesaikan masalah bermakna akan melibatkan gabungan sumber kuantum dan klasikal."},"sidebar":"tutorialsSidebar","previous":{"title":"Asas pengkomputeran kuantum","permalink":"/learning/courses/quantum-business-foundations/quantum-computing-fundamentals"},"next":{"title":"Impak Perniagaan","permalink":"/learning/courses/quantum-business-foundations/business-impacts"}}');var u=e(74848),t=e(28453);const k={title:"Teknologi Kuantum",description:"Kenali bahawa menyelesaikan masalah bermakna akan melibatkan gabungan sumber kuantum dan klasikal."},m="Teknologi IBM Quantum {#ibm-quantum-technology}",r={},l=[{value:"Objektif pembelajaran",id:"learning-objectives",level:2},{value:"IBM Quantum Platform",id:"ibm-quantum-platform",level:3},{value:"Qiskit Runtime",id:"qiskit-runtime",level:3},{value:"Komputer kuantum superkonduksi IBM",id:"ibm-superconducting-quantum-computers",level:3},{value:"Prestasi pengkomputeran kuantum",id:"quantum-computing-performance",level:2},{value:"Mengukur prestasi pengkomputeran kuantum",id:"measuring-quantum-computing-performance",level:3},{value:"Uji pemahaman Anda",id:"check-your-understanding",level:3},{value:"Apa seterusnya dalam pengkomputeran kuantum",id:"whats-next-in-quantum-computing",level:2},{value:"Kegunaan kuantum",id:"quantum-utility",level:3},{value:"Pembetulan Ralat",id:"error-correction",level:3},{value:"Peta Jalan Pembangunan IBM Quantum",id:"ibm-quantum-development-roadmap",level:3},{value:"Cabaran 5k",id:"5k-challenge",level:3},{value:"Superkomputer berpusatkan kuantum",id:"quantum-centric-supercomputers",level:3},{value:"Pengambilan utama",id:"key-takeaways",level:2}];function s(a){const n={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,t.R)(),...a.components},{Details:i,IBMVideo:k}=n;return i||d("Details",!0),k||d("IBMVideo",!0),(0,u.jsxs)(u.Fragment,{children:["\n","\n",(0,u.jsx)(n.header,{children:(0,u.jsx)(n.h1,{id:"ibm-quantum-technology",children:"Teknologi IBM Quantum"})}),"\n",(0,u.jsx)(n.p,{children:"Fleet komputer kuantum IBM\xae, semuanya dengan sekurang-kurangnya 127 qubit, adalah yang terbesar di dunia. Komputer kuantum ini menggunakan qubit transmon superkonduksi, yang bukan satu-satunya jenis qubit, tetapi mempunyai banyak kelebihan. Menggabungkan komputer kuantum bertaraf dunia kami dengan Qiskit membolehkan pengguna kami meneroka bagaimana pengkomputeran kuantum boleh berguna di dunia, hari ini. Rakan industri dan penyelidik menggunakan teknologi IBM Quantum\xae untuk meneroka pengiraan bermakna dan aplikasi realistik. Mari kita terokai pelbagai program dan perkhidmatan yang IBM Quantum tawarkan kepada rakan kongsi."}),"\n",(0,u.jsx)(n.p,{children:"Jika Anda adalah sebahagian daripada institusi yang merupakan ahli IBM Quantum Network, pastikan untuk menghubungi kumpulan pengkomputeran kuantum institusi Anda untuk menentukan faedah apa yang Anda boleh akses."}),"\n",(0,u.jsx)(n.h2,{id:"learning-objectives",children:"Objektif pembelajaran"}),"\n",(0,u.jsx)(n.p,{children:"Menjelang akhir modul ini, Anda sepatutnya boleh:"}),"\n",(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsx)(n.li,{children:"Mengenali bahawa menyelesaikan masalah bermakna akan melibatkan gabungan sumber kuantum dan klasikal."}),"\n",(0,u.jsx)(n.li,{children:"Mengenal pasti perkakasan, perisian, dan perkhidmatan yang tersedia untuk menyelesaikan masalah bermakna."}),"\n",(0,u.jsx)(n.li,{children:"Menerangkan cara mengukur prestasi pengkomputeran kuantum, termasuk skala, kualiti, dan kelajuan."}),"\n"]}),"\n",(0,u.jsx)(n.h3,{id:"ibm-quantum-platform",children:"IBM Quantum Platform"}),"\n",(0,u.jsx)(n.p,{children:"IBM Quantum Platform menyediakan suite alat pengkomputeran kuantum yang menyatukan semua sumber penyelidikan dan pembangunan yang diperlukan pengguna untuk bekerja dengan baik, dalam satu tempat. Pengguna boleh membuat akaun dan log masuk untuk mendapatkan akses ke komputer kuantum IBM, melihat butiran komputer, menjejak beban kerja, dan mengakses bahan pengupayaan dalam Dokumentasi dan Pembelajaran."}),"\n",(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.a,{href:"https://quantum.cloud.ibm.com/",children:"Halaman utama"})," berfungsi sebagai titik permulaan utama untuk ekosistem produk, di mana pengguna boleh mendapatkan kunci API mereka, melihat ringkasan tika dan maklumat penggunaan mereka, melihat butiran kerja terkini, dan mengakses pautan berguna ke tempat lain merentasi platform."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.a,{href:"/docs",children:"Dokumentasi"})," mengagregat dokumentasi Qiskit, dokumentasi perkhidmatan, dan maklumat rujukan API ke dalam satu lokasi, disusun dengan cara yang menyokong aliran kerja semula jadi pengguna."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.a,{href:"/learning",children:"Pembelajaran"})," adalah rumah bagi bahan pendidikan termasuk kursus dan modul pengajaran, serta Circuit Composer interaktif (akan datang). Gabungan penyunting grafik dan kod ini membolehkan pengguna membuat prototaip, mensimulasikan, dan menyahpepijat litar secara visual, kemudian menjalankannya pada komputer kuantum IBM."]}),"\n"]}),"\n",(0,u.jsx)(n.h3,{id:"qiskit-runtime",children:"Qiskit Runtime"}),"\n",(0,u.jsx)(n.p,{children:"Qiskit Runtime adalah seni bina berkontena yang mudah alih dan selamat yang menjalankan program kuantum pada unit pengkomputeran klasikal yang terintegrasi rapat dengan pemproses kuantum. Qiskit Runtime membolehkan komputer kuantum menjadi sebahagian daripada mana-mana persekitaran pengkomputeran untuk mempercepatkan pengiraan \u2014 serupa dengan unit pemproses grafik (GPU) \u2014 dan mengendalikan orkestra kerja dan pemindahan data ke unit pemprosesan kuantum, memaksimumkan kecekapan."}),"\n",(0,u.jsx)(n.p,{children:"Qiskit dan Qiskit Runtime memudahkan untuk mengorkestra program dengan cepat merentasi sumber pengiraan di awan. IBM membina perisian tengah untuk kuantum bagi memaksimumkan prestasi aplikasi kuantum yang berjalan merentasi sumber pengiraan kuantum dan klasikal yang diparalelkan dan berasaskan awan. Perisian tengah ini termasuk kotak alat circuit knitting dan seni bina serverless kuantum kami."}),"\n",(0,u.jsxs)(n.p,{children:[(0,u.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit-addon-cutting",children:"Qiskit addon circuit cutting"})," membolehkan pembangun memotong litar besar kepada litar yang lebih kecil yang sesuai untuk komputer kuantum semasa. Circuit knitting menggunakan pengiraan klasikal untuk mengambil alih sebahagian beban pengiraan litar kuantum bagi melampaui apa yang kita boleh capai dengan mana-mana sahaja. Alat tambahan membantu membina semula litar dengan sumber klasikal dan menyatukan hasil akhir."]}),"\n",(0,u.jsxs)(n.p,{children:[(0,u.jsx)(n.a,{href:"/guides/serverless",children:"Quantum Serverless"})," adalah set alat orkestra berbilang awan untuk menghubungkan sumber klasikal elastik dengan perkhidmatan IBM Qiskit Runtime. Quantum serverless membolehkan pembangun menumpukan pada kod, bukannya penyediaan sumber."]}),"\n",(0,u.jsx)(n.h3,{id:"ibm-superconducting-quantum-computers",children:"Komputer kuantum superkonduksi IBM"}),"\n",(0,u.jsxs)(n.p,{children:["Pemproses kuantum IBM menggunakan jenis qubit fizikal yang dipanggil ",(0,u.jsx)(n.strong,{children:"qubit transmon superkonduksi"}),", yang dibuat daripada bahan superkonduksi yang dibentukkan pada substrat silikon. Pemproses kuantum lain mungkin menggunakan qubit fotonik, yang dibuat daripada foton cahaya tunggal, atau qubit ion terperangkap, yang menyimpan maklumat dalam zarah atom bermuatan. Untuk memudahkan aliran arus elektrik, qubit superkonduksi perlu dikekalkan pada suhu yang sangat rendah \u2014 hampir ke suhu mutlak sifar."]}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.img,{alt:"Pemproses IBM 127-qubit",src:e(60794).A+"",width:"450",height:"450"})}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.em,{children:"Pemproses IBM 127-qubit"})}),"\n",(0,u.jsx)(n.h2,{id:"quantum-computing-performance",children:"Prestasi pengkomputeran kuantum"}),"\n",(0,u.jsx)(n.h3,{id:"measuring-quantum-computing-performance",children:"Mengukur prestasi pengkomputeran kuantum"}),"\n",(0,u.jsx)(n.p,{children:"Komputer kuantum toleransi ralat universal adalah cabaran besar pengkomputeran kuantum. Ia adalah peranti yang boleh melakukan operasi kuantum universal dengan betul menggunakan komponen yang tidak boleh dipercayai. Komputer kuantum hari ini tidak toleransi ralat."}),"\n",(0,u.jsx)(n.p,{children:"Untuk membandingkan komputer kuantum antara satu sama lain, bilangan qubit tidak mencukupi. Banyak butiran lain perlu dipertimbangkan, seperti kadar ralat dan cara sistem disambungkan. Terdapat empat metrik utama untuk mengukur prestasi pengkomputeran kuantum:"}),"\n",(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.strong,{children:"Skala"})," - Diukur dengan ",(0,u.jsx)(n.strong,{children:"bilangan qubit"}),", yang menunjukkan jumlah maklumat yang boleh kita enkod dalam komputer kuantum."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.strong,{children:"Kualiti"})," - Diukur dengan ",(0,u.jsx)(n.strong,{children:"Quantum Volume"}),", yang menunjukkan kualiti litar dan seberapa setia litar dilaksanakan dalam perkakasan."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.strong,{children:"Kelajuan"})," - Diukur dengan ",(0,u.jsx)(n.strong,{children:"CLOPS (Circuit Layer Operations Per Second)"}),", yang menunjukkan berapa banyak litar boleh dijalankan pada perkakasan dalam masa yang diberikan."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.strong,{children:"Kesetiaan Lapisan"})," - Diukur dengan ",(0,u.jsx)(n.strong,{children:"EPLG (Errors Per Layered gate)"}),", yang menerangkan bagaimana ralat berlaku apabila operasi dilakukan pada qubit."]}),"\n"]}),"\n",(0,u.jsxs)(n.p,{children:["Untuk penerangan lebih terperinci tentang beberapa metrik di atas, lihat ",(0,u.jsx)(n.a,{href:"https://www.ibm.com/quantum/blog/quantum-metric-layer-fidelity",children:"artikel ini"})," di Blog Penyelidikan IBM. Setiap fasa dalam penggunaan pengkomputeran kuantum dalam industri didorong oleh peningkatan Quantum Volume, yang dikira menggunakan pelbagai parameter seperti lebar litar, kesambungan qubit, dan kadar ralat."]}),"\n",(0,u.jsx)(n.p,{children:"Definisi teknikal Quantum Volume sukar untuk dikomunikasikan tanpa persamaan.\nDario Gil, Pengarah Penyelidikan di IBM, menerangkan:"}),"\n",(0,u.jsx)(k,{id:"133345140",title:"Dario Gil menerangkan konsep quantum volume. Khususnya dia menerangkan bagaimana dan mengapa ia bergantung pada kedua-dua bilangan qubit dan kadar ralat."}),"\n",(0,u.jsx)(n.p,{children:"Untuk lebih memahami Quantum Volume, pertimbangkan analogi menarik berikut. Bahagian di bawah merangkumi masa, ruang, dan kadar ralat dari segi melakukan lawatan ke New York City."}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.strong,{children:"Melancong keadaan Quantum Volume"})}),"\n",(0,u.jsxs)(n.p,{children:["Quantum Volume menerangkan ruang pengiraan kuantum terbesar yang boleh diterokai oleh komputer kuantum, di mana isipadu ruang kuantum ialah 2",(0,u.jsx)("sup",{children:"N"}),', dengan N adalah bilangan qubit, iaitu dimensi ruang keadaan biasa. Kami sengaja menggunakan perkataan "ruang" di sini kerana setelah kita menyebut ruang, mudah untuk memikirkan isipadu.']}),"\n",(0,u.jsx)(n.p,{children:"Faktor yang mengehadkan penerokaan ini adalah kadar ralat. Kadar ralat boleh disamakan dengan jumlah masa yang kita dibenarkan untuk meneroka ruang. Lebih banyak ralat bermakna lebih sedikit masa untuk meneroka. Semakin banyak ruang pengiraan yang kita miliki, semakin lama masa yang diperlukan untuk meneroka ruang sepenuhnya, dan dengan itu kita memerlukan komputer kuantum dengan kadar ralat yang lebih kecil."}),"\n",(0,u.jsx)(n.p,{children:"Bayangkan seorang pelancong yang meneroka New York City. Pelancong itu ingin meneroka seluruh bandar, bermakna pelancong mahukan isipadu pelancong bersaiz NYC. Jika kita memberi pelancong hanya satu hari, maka tidak mungkin untuk meneroka ruang sebanyak itu, jadi pelancong tidak mendapat isipadu pelancong yang diinginkan. Namun, jika kita memberi pelancong tiga hari, maka pelancong mungkin boleh mengunjungi semua tempat utama dan mendapatkan isipadu pelancong NYC yang diperlukan."}),"\n",(0,u.jsx)(n.p,{children:"Sekarang, bagaimana jika kita memberi pelancong lebih banyak masa tetapi masih mengehadkan ruang ke NYC? Dengan kata lain, bagaimana jika kita mengekalkan bilangan qubit tetapi mengurangkan kadar ralat? Maka tiada faedah kepada pelancong kerana pelancong sudah meneroka bandar dan hanya mengunjungi tempat yang sama berulang kali. Isipadu pelancong tetap sama. Sebaliknya, dengan lebih banyak masa, lebih bijak bagi pelancong untuk mengembangkan bilangan tempat pelancongan yang hendak dikunjungi."}),"\n",(0,u.jsx)(n.p,{children:"Atau, misalkan kita mengekalkan masa tetap pada tiga hari tetapi pelancong memutuskan untuk cuba meneroka semua NYC dan Long Island? Dengan kata lain, bagaimana jika kita menetapkan kadar ralat tetapi menambah lebih banyak qubit? Sekali lagi, isipadu pelancong kekal sebagai NYC kerana pelancong tidak dapat meneroka ruang yang lebih besar dalam masa yang diperuntukkan. Oleh itu, menjadi pelancong yang lebih baik, dan mencapai isipadu pelancong yang lebih besar, memerlukan peningkatan serentak ruang pelancongan dan jumlah masa yang dibenarkan untuk diterokai oleh pelancong."}),"\n",(0,u.jsx)(n.p,{children:"Dengan cara yang sama, membina komputer kuantum yang lebih baik yang mencapai Quantum Volume yang lebih besar memerlukan peningkatan serentak ruang pengiraan kuantum (bilangan qubit) sambil mengurangkan kadar ralat (meningkatkan jumlah masa algoritma boleh berjalan). Sebagai contoh, melalui kemajuan dalam seni bina gandingan boleh laras, IBM menggandakan quantum volume dua kali dalam satu tahun sahaja!"}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.img,{alt:"Quantum Volume",src:e(45223).A+"",width:"720",height:"405"})}),"\n",(0,u.jsx)(n.p,{children:"Namun, apabila pengkomputeran kuantum berkembang, kita mula lebih mengambil berat tentang kerja berguna yang boleh dilakukan oleh komputer kuantum kita dalam masa yang munasabah. Jika kita mengukur skala dengan bilangan qubit, dan kualiti dengan quantum volume, maka kelajuan pemprosesan kuantum adalah ukuran kerja berguna yang boleh dilakukan oleh qubit tersebut dalam masa yang munasabah. Kita mendefinisikannya sebagai bilangan litar primitif yang boleh diproses dalam sesaat. Ia serupa dengan FLOPS dalam pengkomputeran klasikal \u2014 bilangan operasi titik terapung per saat. Meningkatkan kelajuan QPU adalah kunci kepada pengkomputeran kuantum yang praktikal. Seperti pengaturcaraan komputer klasikal, pengaturcaraan kuantum memerlukan menjalankan banyak litar. Kelajuan QPU yang munasabah akan membolehkan pengguna menggabungkan pengkomputeran kuantum sebagai sebahagian daripada aliran kerja mereka."}),"\n",(0,u.jsx)(n.h3,{id:"check-your-understanding",children:"Uji pemahaman Anda"}),"\n",(0,u.jsx)(n.p,{children:"Baca soalan di bawah, fikirkan jawapan Anda, kemudian klik segitiga untuk mendedahkan penyelesaian."}),"\n",(0,u.jsxs)(i,{children:[(0,u.jsx)("summary",{children:(0,u.jsx)(n.p,{children:"Benar atau salah: Quantum Volume merujuk kepada saiz peti sejuk kriogenik yang menempatkan komputer kuantum IBM."})}),(0,u.jsx)(n.p,{children:"Salah. Quantum Volume adalah satu nombor yang bertujuan untuk merangkumkan prestasi komputer kuantum hari ini."})]}),"\n",(0,u.jsx)(n.h2,{id:"whats-next-in-quantum-computing",children:"Apa seterusnya dalam pengkomputeran kuantum"}),"\n",(0,u.jsx)(n.p,{children:"Komputer kuantum hari ini, dan yang dijangkakan untuk masa terdekat, adalah bising. Ini bermakna mereka sensitif terhadap gangguan persekitaran yang boleh mempengaruhi kesetiaan hasil. Sama seperti pengkomputeran klasikal yang berkembang melalui penskalaan modular pemproses, pengiraan yang cekap, dan paralelisasi, kita melihat pengkomputeran kuantum berkembang untuk menyedari potensi penuhnya. Apabila kita bekerja ke arah komputer kuantum toleransi ralat sepenuhnya, kita ingin menyelesaikan masalah berguna dengan perkakasan dan perisian yang kita miliki hari ini."}),"\n",(0,u.jsx)(n.h3,{id:"quantum-utility",children:"Kegunaan kuantum"}),"\n",(0,u.jsx)(n.p,{children:"IBM Quantum dan Universiti California, Berkeley membentangkan bukti bahawa komputer kuantum boleh memberikan nilai lebih awal daripada yang dijangkakan berkat kemajuan dalam perkakasan IBM Quantum dan kaedah mitigasi ralat. Bukan sekadar bukti konsep, kami memberikan hasil yang cukup tepat untuk berguna. Model pengiraan yang kami terokai dengan kerja ini adalah facet teras banyak algoritma yang direka untuk komputer kuantum jangka pendek."}),"\n",(0,u.jsx)(n.p,{children:"Gelung maklum balas antara kuantum dan klasikal adalah kunci untuk memajukan teknologi kuantum. Dengan fokus pada kegunaan kuantum, kita menggunakan kuantum untuk menyelidiki masalah kompleks yang mencabar rangka kerja pengiraan berprestasi tinggi yang sedia ada, kemudian menyemak hasilnya secara klasikal. Proses berulang antara kuantum yang menjalankan litar yang kompleks dan komputer klasikal yang mengesahkan hasil kuantum ini akan meningkatkan kedua-dua domain pengiraan dan memberikan keyakinan kepada pengguna tentang kemampuan komputer kuantum jangka pendek."}),"\n",(0,u.jsx)(k,{id:"134056420",title:"Video ini menggariskan bagaimana komputer kuantum yang bising menggunakan mitigasi ralat untuk mengatasi kaedah klasikal brute force pada contoh masalah."}),"\n",(0,u.jsxs)(i,{children:[(0,u.jsx)("summary",{children:(0,u.jsx)(n.p,{children:"Bacaan pilihan \u2014 klik pada segitiga untuk membaca lebih lanjut tentang eksperimen"})}),(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsxs)(n.li,{children:["\n",(0,u.jsx)(n.p,{children:"Dalam eksperimen ini, kami menggunakan semua 127 qubit pemproses IBM Quantum Eagle kami untuk mensimulasikan perubahan tingkah laku sistem yang secara semula jadi memetakan ke komputer kuantum, yang dipanggil model Ising kuantum. Model Ising adalah penyederhanaan alam semula jadi yang mewakili atom yang berinteraksi sebagai lattice sistem dua pilihan kuantum yang berinteraksi dalam medan tenaga. Sistem ini sangat menyerupai qubit dua keadaan yang membentuk komputer kuantum kita, menjadikannya sesuai untuk menguji kemampuan kaedah kita. Kami menggunakan ZNE untuk cuba mengira secara tepat sifat sistem yang dipanggil nilai jangkaannya \u2014 pada dasarnya purata berwajaran hasil yang mungkin dari litar."}),"\n"]}),"\n",(0,u.jsxs)(n.li,{children:["\n",(0,u.jsx)(n.p,{children:"Secara serentak, pasukan Berkeley mencuba mensimulasikan sistem yang sama menggunakan kaedah rangkaian tensor dengan bantuan superkomputer canggih yang terletak di Pusat Pengiraan Saintifik Penyelidikan Tenaga Kebangsaan (NERSC) Makmal Kebangsaan Lawrence Berkeley dan di Universiti Purdue."}),"\n"]}),"\n",(0,u.jsxs)(n.li,{children:["\n",(0,u.jsx)(n.p,{children:"Kaedah kuantum terus bersetuju dengan kaedah yang tepat. Tetapi akhirnya, kaedah penghampiran klasikal mula goyah apabila kesukaran ditingkatkan."}),"\n"]}),"\n",(0,u.jsxs)(n.li,{children:["\n",(0,u.jsx)(n.p,{children:"Akhirnya, kami meminta kedua-dua komputer untuk menjalankan pengiraan melampaui apa yang boleh dikira dengan tepat \u2014 dan komputer kuantum mengembalikan jawapan yang lebih kami yakin benar. Dan walaupun kita tidak dapat membuktikan sama ada jawapan itu sebenarnya benar, kejayaan Eagle dalam percubaan eksperimen sebelumnya memberi kami keyakinan bahawa ia benar."}),"\n"]}),"\n"]})]}),"\n",(0,u.jsx)(n.h3,{id:"error-correction",children:"Pembetulan Ralat"}),"\n",(0,u.jsx)(n.p,{children:"Pembetulan ralat telah menjadi kawasan penyelidikan utama selama beberapa dekad. Tetapi untuk sebahagian besar masa itu, teknik pembetulan ralat teori tidak praktikal untuk dilaksanakan pada komputer kuantum sebenar, paling kerap kerana jumlah qubit yang sangat besar yang diperlukan. Memang, ramai pakar meramalkan bahawa pengkomputeran kuantum toleransi ralat praktikal (FTQC) akan memerlukan berjuta-juta qubit fizikal. Tetapi dalam makalah terbaru yang diterbitkan di halaman depan Nature, penyelidik dari IBM memperkenalkan kod baru, yang kami sebut kod Gross, yang mengatasi batasan itu."}),"\n",(0,u.jsxs)(n.p,{children:["Makalah ",(0,u.jsx)(n.a,{href:"https://www.nature.com/articles/s41586-024-07107-7",children:"High-threshold and low-overhead fault-tolerant quantum memory"})," menerangkan kod pembetulan ralat kuantum baru yang kira-kira 10 kali lebih cekap berbanding kaedah sebelumnya dalam melindungi data kuantum yang halus daripada ralat yang terkumpul. Untuk mempertimbangkan betapa lebih dekatnya kita kini kepada permulaan pembetulan ralat, pertimbangkan bahawa menggunakan kod Gross, Anda boleh melindungi 12 qubit logik untuk kira-kira sejuta kitaran pemeriksaan ralat menggunakan 288 qubit."]}),"\n",(0,u.jsx)(n.p,{children:"Tidak dijangkakan bahawa pembetulan ralat akan tiba-tiba menggantikan mitigasi ralat dan penindasan ralat. Sebaliknya, dalam beberapa tahun akan datang, mitigasi ralat dan penindasan akan terus memainkan peranan penting, bersama bilangan qubit yang diperbetul ralat yang semakin meningkat."}),"\n",(0,u.jsx)(n.h3,{id:"ibm-quantum-development-roadmap",children:"Peta Jalan Pembangunan IBM Quantum"}),"\n",(0,u.jsx)(n.p,{children:"Kita kini berada dengan kukuh dalam era kegunaan kuantum. Itu bermakna komputer kuantum lebih baik dalam pengkomputeran kuantum berbanding komputer klasikal, dan boleh dimanfaatkan oleh pengguna kami untuk menemui algoritma baru dan mencari kelebihan kuantum. Peta jalan kami menggariskan pencapaian bersejarah dan rancangan kami untuk mencapai kelebihan kuantum jangka pendek menjelang 2026."}),"\n",(0,u.jsxs)(n.p,{children:["Menjelang 2029, kami akan menghantar Starling \u2014 komputer kuantum toleransi ralat berskala besar yang mampu menjalankan litar kuantum yang terdiri daripada 100 juta gerbang kuantum pada 200 qubit logik. Kami sedang membina sistem ini sekarang di kemudahan bersejarah kami di Poughkeepsie, New York. Ketahui lebih lanjut tentang kemajuan kami dalam ",(0,u.jsx)(n.a,{href:"http://www.ibm.com/downloads/documents/us-en/131cf87ab63319bf",children:"PDF Peta Jalan Berpandu."})]}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.img,{alt:"Peta Jalan Pembangunan",src:e(80305).A+"",width:"1920",height:"1080"})}),"\n",(0,u.jsxs)(n.p,{children:["Baca lebih lanjut tentang peta jalan pembangunan IBM Quantum ",(0,u.jsx)(n.a,{href:"https://www.ibm.com/quantum/roadmap",children:"di sini"}),"."]}),"\n",(0,u.jsx)(n.h3,{id:"5k-challenge",children:"Cabaran 5k"}),"\n",(0,u.jsx)(n.p,{children:'IBM bekerjasama dengan komuniti penyelidikan kuantum untuk mencari kes penggunaan berpotensi yang boleh mendapat manfaat daripada pengkomputeran kuantum. Kami menyediakan alat yang semakin berkuasa supaya pengguna boleh meneroka masalah mendesak dengan kuantum. Pada tahun 2024, kami melancarkan alat yang mampu mengira boleh cerap tidak berat sebelah daripada litar panjang dan berkualiti tinggi. Mencari apa yang boleh dilakukan dengan gabungan 100+ qubit dan litar yang dalam pernah dipanggil "cabaran 100x100". Tetapi bilangan qubit dan kedalaman yang tepat pada setiap satunya kurang penting berbanding memanfaatkan kuasa gabungan. Bayangkan apa yang mungkin dengan 5,000 gerbang kuantum dalam satu pengiraan. \u200bPengguna boleh menjalankan litar kuantum dengan kerumitan dan masa jalan melampaui keupayaan komputer klasikal terbaik hari ini. Kami teruja untuk melihat apa yang akan dibina oleh komuniti kuantum untuk membantu kami memanfaatkan kuasa kuantum dan menyelesaikan masalah penting.'}),"\n",(0,u.jsx)(n.h3,{id:"quantum-centric-supercomputers",children:"Superkomputer berpusatkan kuantum"}),"\n",(0,u.jsx)(n.p,{children:"Melampaui pemproses cip tunggal adalah kunci untuk menyelesaikan masalah pada skala. Pada tahun 2024, kami memperkenalkan Crossbill, pemproses tunggal pertama yang dibuat daripada berbilang cip. Ini adalah langkah pertama untuk mengantarkan era penskalaan baru, menyediakan laluan yang jelas ke 100,000 qubit dan lebih dengan superkomputer berpusatkan kuantum. Ini adalah seni bina pengkomputeran modular yang membolehkan penskalaan. Ia menggabungkan komunikasi dan pengiraan kuantum untuk meningkatkan kapasiti pengiraan, sambil menggunakan perisian tengah hybrid cloud untuk mengintegrasikan aliran kerja kuantum dan klasikal dengan lancar."}),"\n",(0,u.jsx)(n.p,{children:"Menyelesaikan masalah paling kompleks di dunia akan memerlukan gabungan sumber klasikal dan kuantum. Tambahan pula, ia akan bergantung pada kerjasama berterusan antara industri dan akademia."}),"\n",(0,u.jsx)(n.h2,{id:"key-takeaways",children:"Pengambilan utama"}),"\n",(0,u.jsx)(n.p,{children:"Anda boleh mengingati pengambilan utama ini:"}),"\n",(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsx)(n.li,{children:"Komputer kuantum hari ini tidak toleransi ralat."}),"\n",(0,u.jsx)(n.li,{children:"Quantum Volume adalah ukuran holistik tentang seberapa baik komputer kuantum. Semakin tinggi Quantum Volume, semakin baik. Bercakap hanya tentang bilangan qubit adalah mengelirukan."}),"\n",(0,u.jsx)(n.li,{children:"Untuk mengukur prestasi komputer kuantum, terdapat empat metrik utama: skala, kualiti, kelajuan, dan kesetiaan lapisan."}),"\n",(0,u.jsx)(n.li,{children:"Eksperimen IBM Quantum-UC Berkeley bersama membentangkan bukti komputer kuantum IBM yang memberikan hasil yang boleh dipercayai dan tepat untuk masalah simulasi yang mencabar pada skala 127 qubit."}),"\n",(0,u.jsx)(n.li,{children:"Superkomputer berpusatkan kuantum bermaksud merawat kuantum sebagai satu bahagian daripada paradigma HPC yang lebih luas dengan klasikal dan kuantum bekerja sebagai satu unit pengiraan."}),"\n"]})]})}function g(a={}){const{wrapper:n}={...(0,t.R)(),...a.components};return n?(0,u.jsx)(n,{...a,children:(0,u.jsx)(s,{...a})}):s(a)}function d(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}},60794(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/127qubit-processer-5f4e07dd161a5396ac24b1af43f9999a.avif"},80305(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/IBM-Quantum-Development-and-Innovation-Roadmap-2025-f5804f9bec56cfc9744c8755f6d3a0a5.svg"},45223(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/QV-ae503518346a4890c4c69e31ee36ea27.avif"},28453(a,n,e){e.d(n,{R:()=>k,x:()=>m});var i=e(96540);const u={},t=i.createContext(u);function k(a){const n=i.useContext(t);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function m(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(u):a.components||u:k(a.components),i.createElement(t.Provider,{value:n},a.children)}}}]);